#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_delete_bt_element_not_found(void) {
    // Build a non-empty tree
    int values[] = {10, 5, 15, 3, 7, 12, 18};
    int size = sizeof(values) / sizeof(values[0]);
    node *root = NULL;
    for (int i = 0; i < size; i++) {
        insert_bt(&root, values[i]);
    }

    // Element that does not exist in the tree
    int ele_not_found = 99;

    // Store the tree state before deletion attempt
    // Capture inorder traversal before
    stdout_capture_t *cap_before = capture_stdout_start();
    inorder_display(root);
    char *output_before = capture_stdout_stop(cap_before);
    free(output_before);

    // Test: delete element not present
    delete_bt(&root, ele_not_found);

    // Capture inorder traversal after
    stdout_capture_t *cap_after = capture_stdout_start();
    inorder_display(root);
    char *output_after = capture_stdout_stop(cap_after);

    // Assert: tree should remain unchanged
    // Since we cannot directly compare the captured strings (they contain newlines),
    // we verify that the tree still contains all original elements
    TEST_ASSERT_NOT_NULL(root);
    // Verify search for original elements still succeeds
    for (int i = 0; i < size; i++) {
        int found = search(root, values[i]);
        TEST_ASSERT_EQUAL_INT(1, found);
    }
    // Verify the missing element is not found
    int not_found = search(root, ele_not_found);
    TEST_ASSERT_EQUAL_INT(0, not_found);

    free(output_after);
    // Cleanup
    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_delete_bt_element_not_found);
    return UNITY_END();
}

